// Helper to get active project from localStorage
function getActiveProject() {
  const activeId = localStorage.getItem('activeProjectId');
  if (!activeId) return null;
  return dbService.getProjectById(activeId);
}

// Helper to save active project
function saveActiveProject(project) {
  if (!project) return;
  dbService.saveProject(project);
}

