export const locationsApi = {
  getLocations: async () => {
    const proj = getActiveProject();
    if (!proj) return { status: 'success', locations: [] };
    
    // Ensure all 46 default locations are always present
    const projectLocs = proj.locations || [];
    const mergedLocations = DEFAULT_SHOW_LOCATIONS.map(defLoc => {
      const existing = projectLocs.find(l => l.location_id === defLoc.location_id);
      if (existing) {
        // Check if the coordinate is one of the old incorrect mock layout coordinates
        const isOldL1 = defLoc.location_id === 'L1' && existing.x_coordinate === 1 && existing.y_coordinate === 2;
        const isOldL2 = defLoc.location_id === 'L2' && existing.x_coordinate === 1 && existing.y_coordinate === 5;
        const isOldL3 = defLoc.location_id === 'L3' && existing.x_coordinate === 1 && existing.y_coordinate === 8;
        const isOldC1 = defLoc.location_id === 'C1' && existing.x_coordinate === 5 && existing.y_coordinate === 2;
        const isOldC2 = defLoc.location_id === 'C2' && existing.x_coordinate === 5 && existing.y_coordinate === 5;
        const isOldC3 = defLoc.location_id === 'C3' && existing.x_coordinate === 5 && existing.y_coordinate === 8;
        const isOldR1 = defLoc.location_id === 'R1' && existing.x_coordinate === 9 && existing.y_coordinate === 2;
        const isOldR2 = defLoc.location_id === 'R2' && existing.x_coordinate === 9 && existing.y_coordinate === 5;
        const isOldR3 = defLoc.location_id === 'R3' && existing.x_coordinate === 9 && existing.y_coordinate === 8;

        const useDefault = isOldL1 || isOldL2 || isOldL3 || isOldC1 || isOldC2 || isOldC3 || isOldR1 || isOldR2 || isOldR3 || projectLocs.length < 46;

        return {
          ...defLoc,
          x_coordinate: useDefault ? defLoc.x_coordinate : (existing.x_coordinate !== undefined && existing.x_coordinate !== null ? existing.x_coordinate : defLoc.x_coordinate),
          y_coordinate: useDefault ? defLoc.y_coordinate : (existing.y_coordinate !== undefined && existing.y_coordinate !== null ? existing.y_coordinate : defLoc.y_coordinate),
          node_hostname: existing.node_hostname || '',
          mac_addr: existing.mac_addr || '',
        };
      }
      return { ...defLoc };
    });

    const defaultIds = new Set(DEFAULT_SHOW_LOCATIONS.map(l => l.location_id));
    projectLocs.forEach(l => {
      if (!defaultIds.has(l.location_id)) {
        mergedLocations.push(l);
      }
    });

    proj.locations = mergedLocations;
    saveActiveProject(proj);
    return { status: 'success', locations: mergedLocations };
  },

  updateLocation: async (locData) => {
    const proj = getActiveProject();
    if (!proj) return { status: 'error', message: 'No active project selected' };

    proj.locations = (proj.locations || []).map(loc => {
      if (loc.location_id === locData.location_id) {
        return { ...loc, ...locData };
      }
      return loc;
    });

    saveActiveProject(proj);
    return { status: 'success' };
  },

  clearLocationAssignments: async () => {
    const proj = getActiveProject();
    if (!proj) return { status: 'error', message: 'No active project selected' };

    proj.locations = (proj.locations || []).map(loc => ({
      ...loc,
      node_hostname: '',
      mac_addr: ''
    }));

    saveActiveProject(proj);
    return { status: 'success' };
  },

  importLocationAssignments: async (file) => {
    // Read and merge locations coordinates from Excel workbook upload
    try {
      const parsed = await importShowWorkbook(file);
      const proj = getActiveProject();
      if (!proj) return { status: 'error', message: 'No active project selected' };

      if (parsed.locations && parsed.locations.length > 0) {
        // Merge or replace
        proj.locations = parsed.locations;
        saveActiveProject(proj);
      }

      return { status: 'success', imported_count: parsed.locations.length };
    } catch (err) {
      return { status: 'error', message: err.message };
    }
  },

  resetLocationsToDefault: async () => {
    const proj = getActiveProject();
    if (!proj) return { status: 'error', message: 'No active project selected' };

    proj.locations = DEFAULT_SHOW_LOCATIONS;
    saveActiveProject(proj);
    return { status: 'success', locations: DEFAULT_SHOW_LOCATIONS };
  }
};

