export const eventsApi = {
  getEvents: async () => {
    const proj = getActiveProject();
    if (!proj) return { status: 'success', events: [] };
    return { status: 'success', events: proj.events || [] };
  },

  getShowInventory: async () => {
    const proj = getActiveProject();
    if (!proj) return { status: 'success', total_units: 0, distinct_types: 0, inventory: [] };

    const inventoryMap = {};
    let totalUnits = 0;

    const eventsList = proj.events || [];
    eventsList.forEach(evt => {
      if (evt.song) return;

      if (evt.fireworks && evt.fireworks.length > 0) {
        evt.fireworks.forEach(fw => {
          if (!fw.firework_name) return;

          let fieldsCount = 0;
          let totalQtyForFw = 0;
          
          if (fw.left_field) {
            fieldsCount++;
            totalQtyForFw += (parseInt(fw.left_qty) || 1);
          }
          if (fw.center_field) {
            fieldsCount++;
            totalQtyForFw += (parseInt(fw.center_qty) || 1);
          }
          if (fw.right_field) {
            fieldsCount++;
            totalQtyForFw += (parseInt(fw.right_qty) || 1);
          }

          if (fieldsCount === 0) totalQtyForFw = 1;

          let fraction = 1.0;
          if (fw.modification) {
            if (fw.modification.includes('1/2')) fraction = 0.5;
            else if (fw.modification.includes('1/3')) fraction = 0.3333;
            else if (fw.modification.includes('1/4')) fraction = 0.25;
          }

          const resolvedCount = totalQtyForFw * fraction;

          if (!inventoryMap[fw.firework_name]) {
            inventoryMap[fw.firework_name] = {
              name: fw.firework_name,
              total_count: 0,
              duration_sec: 0,
              cues_count: 0
            };
          }
          
          inventoryMap[fw.firework_name].total_count += resolvedCount;
          inventoryMap[fw.firework_name].cues_count++;
        });
      }
      else if (evt.relays && evt.relays.length > 0) {
        evt.relays.forEach(r => {
          if (!r.firework_name) return;
          if (!inventoryMap[r.firework_name]) {
            inventoryMap[r.firework_name] = {
              name: r.firework_name,
              total_count: 0,
              duration_sec: 0,
              cues_count: 0
            };
          }
          inventoryMap[r.firework_name].total_count += 1;
          inventoryMap[r.firework_name].cues_count++;
        });
      }
    });

    const catalog = dbService.getCatalog() || [];
    const inventory = Object.values(inventoryMap).map(item => {
      const catFw = catalog.find(c => c.name === item.name);
      item.total_count = parseFloat(item.total_count.toFixed(2));
      return {
        ...item,
        duration_sec: catFw ? parseFloat(catFw.duration_sec) : 0
      };
    });

    const totalCountSum = parseFloat(inventory.reduce((sum, item) => sum + item.total_count, 0).toFixed(2));

    return {
      status: 'success',
      total_units: totalCountSum,
      distinct_types: inventory.length,
      inventory
    };
  },

  saveEvents: async (eventsList) => {
    const proj = getActiveProject();
    if (!proj) return { status: 'error', message: 'No active project selected' };

    proj.events = eventsList;
    saveActiveProject(proj);
    return { status: 'success' };
  },

  deleteEvent: async (eventId) => {
    const proj = getActiveProject();
    if (!proj) return { status: 'error', message: 'No active project selected' };

    proj.events = (proj.events || []).filter(e => (e.event_id || e.event_num) !== eventId);
    saveActiveProject(proj);
    return { status: 'success' };
  },

  importEventsCsv: async (file, clearOnImport = true, forceIgnore = false) => {
    try {
      const proj = getActiveProject();
      if (!proj) return { status: 'error', message: 'No active project selected' };

      let parsedData;
      
      if (file.name.endsWith('.xlsx')) {
        // Multi-tab Excel format import
        parsedData = await importShowWorkbook(file);
      } else {
        // Fallback to CSV parsing
        parsedData = await parseCsvScriptFile(file);
      }

      if (clearOnImport) {
        proj.events = parsedData.events || [];
        if (parsedData.songTracks && parsedData.songTracks.length > 0) {
          proj.songTracks = parsedData.songTracks;
        }
        if (parsedData.locations && parsedData.locations.length > 0) {
          proj.locations = parsedData.locations;
        }
      } else {
        // Merge events
        const existing = proj.events || [];
        const merged = [...existing];
        (parsedData.events || []).forEach(evt => {
          const idx = merged.findIndex(e => e.event_num === evt.event_num);
          if (idx >= 0) merged[idx] = evt;
          else merged.push(evt);
        });
        proj.events = merged.sort((a, b) => a.timestamp_offset_ms - b.timestamp_offset_ms);
      }

      saveActiveProject(proj);
      return { 
        status: 'success', 
        imported_events: parsedData.events.length 
      };
    } catch (err) {
      return { status: 'error', message: `Import error: ${err.message}` };
    }
  },

  exportEventsCsv: async () => {
    // Generate a simple CSV representation of the active script for downloads
    const proj = getActiveProject();
    if (!proj) return null;

    let csvContent = "EventNum,OffsetMs,Title,Relays\n";
    (proj.events || []).forEach(e => {
      const relayStr = (e.relays || []).map(r => 
        `${r.location_id}:${r.relay_idx}:${r.duration_ms}:${r.firework_name}`
      ).join(' & ');
      csvContent += `"${e.event_num}",${e.timestamp_offset_ms},"${e.title.replace(/"/g, '""')}","${relayStr.replace(/"/g, '""')}"\n`;
    });

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `${proj.name.replace(/\s+/g, '_')}_script.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    return { status: 'success' };
  },

  validateEvents: async () => {
    const proj = getActiveProject();
    if (!proj) return { status: 'success', valid: true, errors: [], warnings: [] };

    const errors = [];
    const warnings = [];
    const eventsList = proj.events || [];
    const locationsList = proj.locations || [];

    // Track seen event numbers to find duplicates
    const seenEventNums = {};
    
    eventsList.forEach(e => {
      // Check event_num uniqueness
      if (seenEventNums[e.event_num]) {
        errors.push({
          type: 'DUPLICATE_EVENT_NUM',
          message: `Duplicate event number ${e.event_num} used by event '${e.title}' and '${seenEventNums[e.event_num]}'`
        });
      } else {
        seenEventNums[e.event_num] = e.title;
      }

      // Check empty event (no song and no relays)
      if (!e.song && (!e.relays || e.relays.length === 0)) {
        errors.push({
          type: 'MISSING_RELAYS',
          event_num: e.event_num,
          message: `Event ${e.event_num} ('${e.title}') has no relays assigned.`
        });
        return;
      }

      (e.relays || []).forEach(r => {
        const target = r.location_id;
        
        // Location check
        if (!target || !target.trim()) {
          errors.push({
            type: 'MISSING_LOCATION',
            event_num: e.event_num,
            message: `Event ${e.event_num} ('${e.title}') has a relay actuation with no location assigned.`
          });
          return;
        }

        // Check if location registered in default / current show locations
        const exists = locationsList.some(l => l.location_id === target);
        if (!exists) {
          warnings.push({
            type: 'UNREGISTERED_LOCATION',
            event_num: e.event_num,
            message: `Location ${target} used in event #${e.event_num} is not registered in show layout`
          });
        }

        // Validate relay index limits
        if (r.relay_idx === -1 || r.relay_idx === undefined || r.relay_idx === null) {
          warnings.push({
            type: 'UNASSIGNED_RELAY',
            event_num: e.event_num,
            message: `Event ${e.event_num} ('${e.title}') has a relay actuation with no Relay Port assigned.`
          });
        } else if (r.relay_idx < 0 || r.relay_idx > 7) {
          errors.push({
            type: 'INVALID_RELAY_INDEX',
            event_num: e.event_num,
            message: `Event ${e.event_num} uses invalid relay index ${r.relay_idx + 1} (must be 1-8).`
          });
        }

        // Validate duration
        if (r.duration_ms <= 0) {
          errors.push({
            type: 'INVALID_DURATION',
            event_num: e.event_num,
            message: `Event ${e.event_num} has invalid duration ${r.duration_ms}ms (must be > 0).`
          });
        }
      });
    });

    // Check overlaps
    // Map of location_id -> relay_idx -> list of {start, end, num, title}
    const relayTimelines = {};
    eventsList.forEach(e => {
      if (e.song) return;
      (e.relays || []).forEach(r => {
        if (r.location_id && r.relay_idx !== -1 && r.relay_idx !== undefined && r.relay_idx >= 0 && r.relay_idx <= 7) {
          if (!relayTimelines[r.location_id]) {
            relayTimelines[r.location_id] = {};
            for (let i = 0; i < 8; i++) relayTimelines[r.location_id][i] = [];
          }
          const start = e.timestamp_offset_ms || 0;
          const end = start + (r.duration_ms || 2000);
          relayTimelines[r.location_id][r.relay_idx].push({ start, end, num: e.event_num, title: e.title });
        }
      });
    });

    Object.keys(relayTimelines).forEach(loc => {
      for (let rIdx = 0; rIdx < 8; rIdx++) {
        const intervals = relayTimelines[loc][rIdx];
        intervals.sort((a, b) => a.start - b.start);
        for (let i = 0; i < intervals.length - 1; i++) {
          const curr = intervals[i];
          const next = intervals[i+1];
          if (curr.end > next.start) {
            errors.push({
              type: 'OVERLAP',
              message: `Overlapping firing on Location ${loc} Relay ${rIdx + 1}: Event ${curr.num} ('${curr.title}', ends at ${curr.end}ms) overlaps Event ${next.num} ('${next.title}', starts at ${next.start}ms).`
            });
          }
        }
      }
    });

    return {
      status: 'success',
      valid: errors.length === 0,
      errors,
      warnings
    };
  }
};

