  // Timing formatting and parsing helpers
  const formatMsToTimeString = (ms) => {
    if (ms === undefined || ms === null || isNaN(ms)) return '00:00.000';
    const mins = Math.floor(ms / 60000);
    const secs = Math.floor((ms % 60000) / 1000);
    const msecs = Math.floor(ms % 1000);
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}.${msecs.toString().padStart(3, '0')}`;
  };

  const formatMsToSecondsOnlyString = (ms) => {
    if (ms === undefined || ms === null || isNaN(ms)) return '0.000';
    return (ms / 1000).toFixed(3);
  };

  const formatEventNum = (numStr) => {
    if (!numStr) return '';
    const parts = numStr.split('.');
    if (parts.length > 2) {
      const last = parts[parts.length - 1];
      const baseStr = parts.slice(0, -1).join('.');
      const baseNum = parseFloat(baseStr);
      if (!isNaN(baseNum)) {
        const rounded = Math.round(baseNum * 10000) / 10000;
        return `${rounded}.${last}`;
      }
    } else {
      const num = parseFloat(numStr);
      if (!isNaN(num)) {
        return (Math.round(num * 10000) / 10000).toString();
      }
    }
    return numStr;
  };

  const parseTimeStringToMs = (str) => {
    if (!str) return 0;
    const trimmed = str.trim();
    const parts = trimmed.split(':');
    if (parts.length === 2) {
      const mins = parseInt(parts[0], 10);
      const secondsParts = parts[1].split('.');
      const secs = parseInt(secondsParts[0], 10);
      let msecs = 0;
      if (secondsParts.length === 2) {
        msecs = parseInt(secondsParts[1].padEnd(3, '0').substring(0, 3), 10);
      }
      if (isNaN(mins) || isNaN(secs) || isNaN(msecs)) return null;
      return mins * 60000 + secs * 1000 + msecs;
    } else if (parts.length === 1) {
      const secondsParts = parts[0].split('.');
      if (secondsParts.length === 2) {
        const secs = parseInt(secondsParts[0], 10);
        const msecs = parseInt(secondsParts[1].padEnd(3, '0').substring(0, 3), 10);
        if (isNaN(secs) || isNaN(msecs)) return null;
        return secs * 1000 + msecs;
      } else {
        const num = parseInt(parts[0], 10);
        if (!isNaN(num)) return num;
      }
    }
    return null;
  };

  const getEventSortingTime = (evt) => evt.desired_time_ms !== undefined && evt.desired_time_ms !== null ? evt.desired_time_ms : (evt.timestamp_offset_ms || 0);

  const resequenceEvents = (eventsList) => {
    const songs = eventsList.filter(e => e.song).sort((a, b) => getEventSortingTime(a) - getEventSortingTime(b));
    const cues = eventsList.filter(e => !e.song).sort((a, b) => getEventSortingTime(a) - getEventSortingTime(b));

    songs.forEach((s, idx) => {
      s.event_num = `S${idx + 1}`;
    });

    const updatedCues = cues.map(cue => {
      let activeSongNum = 0;
      for (let i = 0; i < songs.length; i++) {
        if (getEventSortingTime(songs[i]) <= getEventSortingTime(cue)) {
          activeSongNum = i + 1;
        }
      }
      return { ...cue, activeSongNum };
    });

    const songGroups = {};
    updatedCues.forEach(cue => {
      const g = cue.activeSongNum;
      if (!songGroups[g]) songGroups[g] = [];
      songGroups[g].push(cue);
    });

    const finalCues = [];
    Object.keys(songGroups).forEach(g => {
      const groupCues = songGroups[g].sort((a, b) => getEventSortingTime(a) - getEventSortingTime(b));
      groupCues.forEach((c, idx) => {
        c.event_num = `${g}.${idx + 1}`;
        delete c.activeSongNum;
        finalCues.push(c);
      });
    });

    return [...songs, ...finalCues].sort((a, b) => getEventSortingTime(a) - getEventSortingTime(b));
  };
  const generateEventTitle = (fwList) => {
    if (!fwList || fwList.length === 0) return 'Empty Cue';

    const parts = fwList.map(fw => {
      if (!fw.firework_name) return '';

      let fieldsStr = '';
      const fieldList = [];
      if (fw.left_field) fieldList.push('L');
      if (fw.center_field) fieldList.push('C');
      if (fw.right_field) fieldList.push('R');
      
      const fieldsName = fieldList.join('');
      if (fw.is_field_effect) {
        fieldsStr = `FIELD ${fieldsName ? fieldsName + ' ' : ''}`;
      } else {
        fieldsStr = fieldsName ? `${fieldsName} - ` : '';
      }

      let modStr = '';
      if (fw.modification && fw.modification !== 'None') {
        let label = fw.modification;
        if (fw.modification.includes('1/2')) label = 'MOD – 1/2 seg';
        else if (fw.modification.includes('1/3')) label = 'MOD – 1/3 seg';
        else if (fw.modification.includes('1/4')) label = 'MOD – 1/4 seg';
        else if (fw.modification === 'Flash All') label = 'MOD – Flash All';
        
        modStr = `(${label}) `;
      }
      
      if (fw.flash_fused && !modStr.includes('Flash')) {
        modStr = `(MOD - Flash Fuse) ${modStr}`;
      }

      let qtyStr = '';
      const leftQty = parseInt(fw.left_qty) || 1;
      const centerQty = parseInt(fw.center_qty) || 1;
      const rightQty = parseInt(fw.right_qty) || 1;
      
      let commonQty = 1;
      let qtyDetails = '';

      if (fw.left_field && fw.center_field && fw.right_field) {
        if (leftQty === centerQty && centerQty === rightQty) {
          commonQty = leftQty;
        } else {
          qtyDetails = ` (L:x${leftQty}, C:x${centerQty}, R:x${rightQty})`;
        }
      } else if (fw.left_field && fw.center_field) {
        if (leftQty === centerQty) commonQty = leftQty;
        else qtyDetails = ` (L:x${leftQty}, C:x${centerQty})`;
      } else if (fw.center_field && fw.right_field) {
        if (centerQty === rightQty) commonQty = centerQty;
        else qtyDetails = ` (C:x${centerQty}, R:x${rightQty})`;
      } else if (fw.left_field && fw.right_field) {
        if (leftQty === rightQty) commonQty = leftQty;
        else qtyDetails = ` (L:x${leftQty}, R:x${rightQty})`;
      } else {
        commonQty = fw.left_field ? leftQty : (fw.center_field ? centerQty : rightQty);
      }

      if (commonQty > 1 && !qtyDetails) {
        qtyStr = ` x${commonQty}`;
      } else if (qtyDetails) {
        qtyStr = qtyDetails;
      }

      return `${fieldsStr}${modStr}${fw.firework_name}${qtyStr}`;
    }).filter(Boolean);

    return parts.join(' & ');
  };
  const getNextEventNumAtTime = (ms, eventsList = events) => {
    const songs = [...eventsList].filter(e => e.song).sort((a, b) => getEventSortingTime(a) - getEventSortingTime(b));
    
    let activeSongNum = 0;
    let windowStart = 0;
    let windowEnd = Infinity;
    
    for (let i = 0; i < songs.length; i++) {
      if (songs[i].timestamp_offset_ms <= ms) {
        activeSongNum = parseInt(songs[i].event_num.replace('S', '')) || (i + 1);
        windowStart = songs[i].timestamp_offset_ms;
        windowEnd = songs[i + 1] ? songs[i + 1].timestamp_offset_ms : Infinity;
      }
    }
    
    if (activeSongNum === 0 && songs.length > 0 && ms < songs[0].timestamp_offset_ms) {
      windowEnd = songs[0].timestamp_offset_ms;
    }
    
    const windowCues = eventsList.filter(e => 
      !e.song && 
      e.timestamp_offset_ms >= windowStart && 
      e.timestamp_offset_ms < windowEnd
    );
    
    let maxY = 0;
    windowCues.forEach(c => {
      if (c.event_num && c.event_num.includes('.')) {
        const parts = c.event_num.split('.');
        const y = parseInt(parts[1]) || 0;
        if (y > maxY) maxY = y;
      } else if (c.event_num) {
        const y = parseInt(c.event_num) || 0;
        if (y > maxY) maxY = y;
      }
    });
    
    return `${activeSongNum}.${maxY + 1}`;
  };

